#!/usr/bin/env python3
"""
playwright_parser — парсинг чеков РФ через Playwright + Chromium (headless).
Обходит JS-защиту proverkacheka.com, извлекает товары в JSON.
"""

import json
import sys
import re
import os
from pathlib import Path
from bs4 import BeautifulSoup
from playwright.sync_api import sync_playwright

BASE_URL = "https://proverkacheka.com"


def parse_qr(qr_string: str, headless: bool = True, timeout: int = 40000) -> dict:
    """
    Проверить чек через proverkacheka.com по QR-строке.
    Использует page.evaluate() для обхода антибот-защиты.
    """
    result = {"success": False, "qr": qr_string, "data": None, "raw_html": "", "error": ""}

    with sync_playwright() as p:
        browser = p.chromium.launch(headless=headless)
        context = browser.new_context(
            user_agent="Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36",
            viewport={"width": 1280, "height": 900},
            locale="ru-RU",
            timezone_id="Asia/Novosibirsk",
            extra_http_headers={
                "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/apng,*/*;q=0.8",
                "Accept-Language": "ru-RU,ru;q=0.9,en-US;q=0.8,en;q=0.7",
            }
        )
        page = context.new_page()
        page.set_default_timeout(timeout)

        try:
            # 1. Открыть сайт — ждём загрузки DOM
            page.goto(BASE_URL, wait_until="domcontentloaded")
            page.wait_for_timeout(3000)  # дать время на JS и защиту

            # Имитация человеческого поведения
            page.evaluate("window.scrollTo(0, 300)")
            page.wait_for_timeout(1000)
            page.evaluate("window.scrollTo(0, 0)")
            page.wait_for_timeout(1000)

            # 2. Ждать появления формы
            try:
                page.wait_for_selector("#b-checkform_qrraw", timeout=20000)
            except:
                result["error"] = "Форма не загрузилась (возможно Cloudflare)"
                browser.close()
                return result

            page.wait_for_timeout(1000)

            # 3. Ввести QR-строку через JS (антибот блокирует fill())
            page.evaluate(f"""
                (() => {{
                    const el = document.getElementById('b-checkform_qrraw');
                    if (!el) return false;
                    el.value = {json.dumps(qr_string)};
                    el.dispatchEvent(new Event('input', {{bubbles: true}}));
                    el.dispatchEvent(new Event('change', {{bubbles: true}}));
                    el.dispatchEvent(new Event('blur', {{bubbles: true}}));
                    return true;
                }})()
            """)

            # 4. Проверить что значение вставилось
            val = page.evaluate('document.getElementById("b-checkform_qrraw").value')
            if not val or len(val) < 10:
                result["error"] = f"QR не вставился в поле (value={val!r})"
                browser.close()
                return result

            # 5. Нажать кнопку «Проверить» через JS
            page.evaluate("""
                (() => {
                    const btn = document.querySelector('button.b-checkform_btn-send');
                    if (btn) {
                        btn.click();
                        return true;
                    }
                    // fallback — ищем любую кнопку "Проверить"
                    const allBtns = document.querySelectorAll('button');
                    for (const b of allBtns) {
                        if (b.textContent.trim() === 'Проверить') {
                            b.click();
                            return true;
                        }
                    }
                    return false;
                })()
            """)

            # 6. Ждать результат
            page.wait_for_timeout(5000)

            # 7. Проверить диалог "чек недоступен"
            try:
                has_dialog = page.evaluate("""
                    () => !!document.querySelector('.modal-header:has-text("Внимание!"), dialog')
                """)
                if has_dialog:
                    result["error"] = "Чек не найден в базе ФНС"
                    # Закрыть диалог
                    page.evaluate("""
                        () => {
                            const closeBtn = document.querySelector('button:has-text("Закрыть")');
                            if (closeBtn) closeBtn.click();
                        }
                    """)
                    browser.close()
                    return result
            except:
                pass

